/* ===== Recursos Humanos (v3.5) · basado en el módulo de la demo DIPARMA (Sistema VB V27), adaptado a esta organización =====
   · Legajos del equipo (alta, baja con historial, contrato, modalidad por hora o mensual, PIN de fichaje, tarjeta QR/NFC firmada).
   · Turnos semanales y licencias en el mismo calendario; tardanzas, ausencias y fichadas incompletas salen solas de los fichajes.
   · Solicitudes (vacaciones, licencias, enfermedad…) con aprobación en niveles configurables (Supervisor → RR. HH. → Administración).
   · Vacaciones por antigüedad (tabla editable, por defecto 14/21/28/35 días corridos) [VERIFICAR con el contador].
   · Nómina INTERNA: horas, extras, tardanzas, ausencias y deducciones configurables. No reemplaza el recibo de haberes legal.
   · Documentos con vencimiento, reclutamiento por etapas, avisos al personal y portal del empleado en modo kiosco (PIN).
   · En la nube viajan los registros; los archivos adjuntos quedan en el equipo donde se cargaron (y en su respaldo). */
const HR_REQ_T={vacaciones:'Vacaciones',licencia:'Licencia',enfermedad:'Enfermedad',estudio:'Examen o estudio',justificante:'Justificante',otro:'Otro'};
const HR_STAGES=[['recibido','CV recibido'],['entrevista','Entrevista'],['prueba','Prueba'],['oferta','Oferta'],['contratado','Contratado'],['descartado','Descartado']];
const HR_DOC_T={dni:'DNI',contrato:'Contrato',alta:'Alta temprana',art:'ART / seguro',certificado:'Certificado',capacitacion:'Capacitación',cv:'CV',otro:'Otro'};
const HR_FLOW_T={supervisor:'Supervisor',rrhh:'RR. HH.',admin:'Administración'};
const HR_DEF={tol:10,otDaily:8,otFactor:1.5,otSun:2,monthHours:200,lateDisc:false,absDisc:false,deds:[],flow:['supervisor','admin'],vacTable:[[0,14],[5,21],[10,28],[20,35]],portal:true};
const HR_FILE_MAX=1500000;
/* la configuración se lee sin tocar S.org (sólo Ajustes la guarda) */
function hrCfg(){const o=(S.org&&S.org.hr&&typeof S.org.hr==='object')?S.org.hr:{};const c=Object.assign({},HR_DEF,o);
 if(!Array.isArray(c.flow)||!c.flow.length)c.flow=HR_DEF.flow.slice();if(!Array.isArray(c.vacTable)||!c.vacTable.length)c.vacTable=HR_DEF.vacTable;if(!Array.isArray(c.deds))c.deds=[];return c}
function hrInit(){for(const k of ['hrShifts','hrReqs','hrDocs','hrPays','hrJobs','hrCands','hrMsgs','hrReads'])if(!Array.isArray(S[k]))S[k]=[];if(!S.hrFiles||typeof S.hrFiles!=='object')S.hrFiles={};
 for(const f of S.staff){if(f.active==null)f.active=true;if(!f.payMode)f.payMode='hora'}}
const hrE=id=>S.staff.find(f=>f.id===id)||null;
const hrAct=()=>S.staff.filter(f=>f.active!==false);
const hrMin=s=>{const m=/^(\d{1,2}):(\d{2})$/.exec(String(s||''));return m?(+m[1])*60+(+m[2]):NaN};
const hrTs=(day,hm)=>new Date(day+'T'+(hm||'00:00')+':00').getTime();
const addDays=(k,n)=>dkey(new Date(k+'T12:00:00').getTime()+n*864e5);
const dowK=k=>new Date(k+'T12:00:00').getDay();
function hrDays(from,to){const o=[];let k=from,g=0;while(k<=to&&g++<400){o.push(k);k=addDays(k,1)}return o}
const hrShift=(sid,day)=>S.hrShifts.find(s=>s.staffId===sid&&s.day===day)||null;
const hrLeave=(sid,day)=>S.hrReqs.find(r=>r.staffId===sid&&r.state==='aprobada'&&r.from<=day&&r.to>=day)||null;
const hrPunches=(sid,day)=>S.fichajes.filter(x=>x.staffId===sid&&dkey(x.t)===day).sort((a,b)=>a.t-b.t);
const hrLast=sid=>S.fichajes.filter(x=>x.staffId===sid).sort((a,b)=>b.t-a.t)[0]||null;
function hrHoursDay(sid,day){const ps=hrPunches(sid,day);let h=0,open=null,flag=false;for(const p of ps){if(p.type==='in'){if(open!==null)flag=true;open=p.t}else{if(open===null){flag=true;continue}h+=(p.t-open)/36e5;open=null}}
 if(open!==null&&day<today())flag=true;return{h:r2(h),flag,ps,open:open!==null&&day===today()}}
function hrDay(f,day){const c=hrCfg();const x=hrHoursDay(f.id,day);const sh=hrShift(f.id,day);const lv=hrLeave(f.id,day);const ins=x.ps.filter(p=>p.type==='in');let late=0;
 if(sh&&ins.length){const d=Math.round((ins[0].t-hrTs(day,sh.from))/60000);if(d>c.tol)late=d}
 const shH=sh?Math.max(0,((hrMin(sh.to)-hrMin(sh.from)+1440)%1440)/60):0;
 const past=sh?hrTs(day,sh.from)+c.tol*60000<now():false;
 const absent=!!(sh&&!lv&&!ins.length&&past);
 return{h:x.h,flag:x.flag,open:x.open,sh,shH,lv,late,absent,ot:Math.max(0,r2(x.h-c.otDaily)),sun:dowK(day)===0,ps:x.ps}}
function hrStats(f,from,to){const o={days:0,h:0,ot:0,otSun:0,late:0,lateN:0,abs:0,absH:0,flags:0,lv:{}};const lim=today();
 for(const d of hrDays(from,to>lim?lim:to)){const x=hrDay(f,d);if(x.h>0)o.days++;o.h+=x.h;if(x.sun)o.otSun+=x.ot;else o.ot+=x.ot;if(x.late){o.late+=x.late;o.lateN++}if(x.absent){o.abs++;o.absH+=x.shH}if(x.flag)o.flags++;if(x.lv)o.lv[x.lv.type]=(o.lv[x.lv.type]||0)+1}
 o.h=r2(o.h);o.ot=r2(o.ot);o.otSun=r2(o.otSun);return o}
const monthRange=m=>{const a=m+'-01';const b=addDays(addDays(a,32).slice(0,7)+'-01',-1);return[a,b]};
/* ---------- nómina interna ---------- */
const hrHourly=f=>f?(f.payMode==='mes'?r2((+f.salary||0)/Math.max(1,hrCfg().monthHours)):(+f.rate||0)):0;
function hrPayLine(f,period){const c=hrCfg();const [a,b]=monthRange(period);const st=hrStats(f,a,b);const hv=hrHourly(f);const mes=f.payMode==='mes';
 const base=mes?(+f.salary||0):Math.round(st.h*(+f.rate||0));
 const otAmt=Math.round(st.ot*hv*(c.otFactor-(mes?0:1))+st.otSun*hv*(c.otSun-(mes?0:1)));
 const lateAmt=c.lateDisc?Math.round(st.late/60*hv):0;const absAmt=c.absDisc&&mes?Math.round(st.absH*hv):0;
 const gross=Math.max(0,base+otAmt-lateAmt-absAmt);const deds=c.deds.map(d=>({n:d.n,a:Math.round(gross*(+d.pct||0)/100)}));const net=gross-deds.reduce((x,d)=>x+d.a,0);
 return{staffId:f.id,name:f.name,role:f.role||'',mode:mes?'mensual':'por hora',hours:st.h,ot:r2(st.ot+st.otSun),late:st.late,abs:st.abs,base,otAmt,lateAmt,absAmt,gross,deds,net}}
function hrPayCalc(period){const [a,b]=monthRange(period);return S.staff.filter(f=>f.active!==false||S.fichajes.some(p=>p.staffId===f.id&&dkey(p.t)>=a&&dkey(p.t)<=b)).map(f=>hrPayLine(f,period))}
/* ---------- vacaciones ---------- */
function hrVacYears(f,year){if(!f.hire)return 0;const h=f.hire;let y=year-(+h.slice(0,4));if(h.slice(5)>'12-31')y--;return Math.max(0,y)}
function hrVacEntitled(f,year){const c=hrCfg();if(!f.hire)return +f.vacExtra||0;const yrs=hrVacYears(f,year);let d=0;for(const [y,n] of c.vacTable)if(yrs>=y)d=n;return d+(+f.vacExtra||0)}
function hrVacTaken(f,year,st){const a=year+'-01-01',b=year+'-12-31';return S.hrReqs.filter(r=>r.staffId===f.id&&r.type==='vacaciones'&&r.state===st).reduce((x,r)=>x+hrDays(r.from<a?a:r.from,r.to>b?b:r.to).length,0)}
/* ---------- avisos ---------- */
function hrAlerts(){hrInit();const out=[];const t=today(),lim=addDays(t,30);
 for(const f of hrAct()){
  if(f.cEnd&&f.cEnd<=lim)out.push({c:f.cEnd<t?'bad':'warn',k:'contrato',tab:'legajos',t:'Contrato de '+f.name+(f.cEnd<t?' vencido el ':' termina el ')+fdate(f.cEnd)});
  const x=hrDay(f,t);if(x.absent)out.push({c:'bad',k:'asistencia',tab:'asistencia',t:f.name+': tenía turno a las '+x.sh.from+' y no fichó'});else if(x.late)out.push({c:'warn',k:'asistencia',tab:'asistencia',t:f.name+': llegó '+x.late+' min tarde hoy'});
  for(const d of hrDays(addDays(t,-7),addDays(t,-1)))if(hrHoursDay(f.id,d).flag)out.push({c:'warn',k:'asistencia',tab:'asistencia',t:f.name+': fichada incompleta el '+fdate(d)})}
 for(const d of S.hrDocs)if(d.exp&&d.exp<=lim){const f=hrE(d.staffId);if(f&&f.active!==false)out.push({c:d.exp<t?'bad':'warn',k:'documento',tab:'documentos',t:(HR_DOC_T[d.kind]||'Documento')+' de '+f.name+(d.exp<t?' vencido el ':' vence el ')+fdate(d.exp)})}
 const pend=S.hrReqs.filter(r=>r.state==='pendiente').length;if(pend)out.push({c:'warn',k:'solicitudes',tab:'solicitudes',t:pend+' solicitud(es) del personal esperando aprobación'});
 return out}
function hrAlertsShort(){let a=[];try{a=hrAlerts()}catch(e){return[]}const by={};for(const x of a)(by[x.k]=by[x.k]||[]).push(x);
 return Object.keys(by).map(k=>{const l=by[k];const c=l.some(x=>x.c==='bad')?'bad':'warn';return[c,'RR. HH.: '+esc(l[0].t)+(l.length>1?' y '+(l.length-1)+' más':''),'personal:'+l[0].tab]})}

/* ---------- PIN y fichaje ---------- */
const hrPinH=(id,pin)=>sha256s('hrpin|'+id+'|'+pin);
const hrByPin=pin=>hrAct().find(f=>f.pinH&&f.pinH===hrPinH(f.id,pin))||null;
function hrPunch(f,method,extra){
 if(!f||f.active===false)return{err:'Empleado dado de baja'};
 const last=hrLast(f.id);if(last&&now()-last.t<60000&&method!=='manual')return{err:'Fichada repetida: esperá 60 segundos.'};
 const type=extra&&extra.type?extra.type:(last&&last.type==='in'&&dkey(last.t)===today()?'out':'in');
 const p=Object.assign({id:uid(),staffId:f.id,t:now(),type,method},extra||{});p.type=type;
 S.fichajes.push(p);audit('fichaje',{empleado:f.name,tipo:type,medio:method});persist();return{p}}
async function fichar(tok){
 const r=await verifyToken(tok);const out=$('#fi_r');const say=(m,ok)=>{if(out)out.innerHTML='<b class="'+(ok?'ok-t':'bad-t')+'">'+esc(m)+'</b>';toast(m)};
 if(r.err)return say(r.err,false);if(r.kind!=='TF1')return say('Esa tarjeta es de un socio, no de personal',false);
 S.scans=S.scans||{};for(const k of Object.keys(S.scans))if(now()-S.scans[k]>300000)delete S.scans[k];
 if(S.scans[r.sig]&&now()-S.scans[r.sig]<60000)return say('Lectura repetida (esperá 60 s)',false);
 S.scans[r.sig]=now();const x=hrPunch(r.ent,'tarjeta');if(x.err)return say(x.err,false);refresh();
 const o2=$('#fi_r');if(o2)o2.innerHTML='<b class="ok-t">'+esc(r.ent.name)+': '+(x.p.type==='in'?'INGRESO':'EGRESO')+' '+fdt(now()).slice(11)+'</b>';toast(r.ent.name+': '+(x.p.type==='in'?'ingreso':'egreso'))}
A.fichTok=()=>{const v=$('#fi_t').value;$('#fi_t').value='';fichar(v)};
A.fichCam=()=>scanCamera(fichar);A.fichNfc=()=>scanNFC(fichar);
KD.fich=(el,e)=>{if(e.key==='Enter'){e.preventDefault();A.fichTok()}};
const HRF={fail:0,until:0};
A.fichPin=()=>{const i=$('#fi_p');const pin=(i.value||'').replace(/\D/g,'');i.value='';const out=$('#fi_r');
 if(now()<HRF.until)return toast('Demasiados intentos: esperá un minuto');if(pin.length<4)return toast('El PIN tiene 4 a 6 dígitos');
 const f=hrByPin(pin);if(!f){HRF.fail++;if(HRF.fail>=5){HRF.until=now()+60000;HRF.fail=0;audit('fichaje_pin','5 PIN incorrectos: bloqueo 1 minuto')}if(out)out.innerHTML='<b class="bad-t">PIN incorrecto</b>';return}
 HRF.fail=0;const x=hrPunch(f,'pin');if(x.err){if(out)out.innerHTML='<b class="bad-t">'+esc(x.err)+'</b>';return}refresh();const o2=$('#fi_r');if(o2)o2.innerHTML='<b class="ok-t">'+esc(f.name)+': '+(x.p.type==='in'?'INGRESO':'EGRESO')+' '+fdt(now()).slice(11)+'</b>';toast(f.name+': '+(x.p.type==='in'?'ingreso':'egreso'))};
KD.fichPin=(el,e)=>{if(e.key==='Enter'){e.preventDefault();A.fichPin()}};

/* ===================== VISTA «Recursos Humanos» ===================== */
const HR={tab:'inicio',week:'',m:'',from:'',to:'',sel:'',q:'',rf:'pendiente',job:'',docf:'',vy:0,bajas:false};
const HR_TABS=[['inicio','Resumen','grid'],['legajos','Legajos','idcard'],['turnos','Turnos y licencias','cal'],['asistencia','Asistencia','clock'],['solicitudes','Solicitudes','inbox'],['vacaciones','Vacaciones','star'],['nomina','Nómina','cash','gestionar'],['documentos','Documentos','file'],['reclutamiento','Reclutamiento','users'],['avisos','Avisos al personal','bell'],['ajustes','Ajustes','gear','admin']];
const hrTabOk=t=>{const x=HR_TABS.find(y=>y[0]===t);if(!x)return false;if(x[3]==='admin')return can('admin');if(x[3])return mayo('personal',x[3]);return true};
const hrW=()=>mayo('personal','cargar');
const hrBadge=t=>{if(t==='solicitudes'){const n=S.hrReqs.filter(r=>r.state==='pendiente').length;return n?' <span class="badge warn">'+n+'</span>':''}if(t==='inicio'){const n=hrAlerts().length;return n?' <span class="badge warn">'+n+'</span>':''}return''};
function hrEmpSel(id,sel,all,lbl){return '<select id="'+id+'" class="sel" aria-label="'+esc(lbl||'Empleado')+'">'+(all?'<option value="">'+esc(all)+'</option>':'')+hrAct().map(f=>'<option value="'+f.id+'"'+(sel===f.id?' selected':'')+'>'+esc(f.name)+'</option>').join('')+'</select>'}
function hrKpi(l,v,sub,cls){return '<div class="c '+(cls||'')+' s3"><span class="lbl">'+esc(l)+'</span><div class="kpi">'+v+'</div>'+(sub?'<span class="sub">'+sub+'</span>':'')+'</div>'}
VIEWS.personal={t:'Recursos Humanos',r(){
 hrInit();if(!hrTabOk(HR.tab))HR.tab='inicio';
 const tabs='<div class="htabs" role="tablist" aria-label="Secciones de Recursos Humanos">'+HR_TABS.filter(x=>hrTabOk(x[0])).map(x=>'<button type="button" role="tab" aria-selected="'+(HR.tab===x[0])+'" data-a="hrTab" data-id="'+x[0]+'">'+ic(x[2])+'<span>'+x[1]+hrBadge(x[0])+'</span></button>').join('')+'</div>';
 const body=({inicio:hrInicio,legajos:hrLegajos,turnos:hrTurnos,asistencia:hrAsistencia,solicitudes:hrSolicitudes,vacaciones:hrVacaciones,nomina:hrNomina,documentos:hrDocumentos,reclutamiento:hrReclut,avisos:hrAvisos,ajustes:hrAjustes}[HR.tab])();
 return '<div class="ph"><div><h1>Recursos Humanos</h1><span class="sub">'+hrAct().length+' legajo(s) activo(s) · '+esc(S.org.brand||'')+'</span></div><div class="row">'+(hrW()?'<button class="btn y" data-a="hrEmpNew">'+ic('plus')+'Nuevo legajo</button>':'')+(allowed('fichaje')?'<button class="btn g" data-a="nav" data-id="fichaje">'+ic('nfc')+'Fichaje y kiosco</button>':'')+'</div></div>'+tabs+'<div class="hrbody">'+body+'</div>'}};
A.hrTab=el=>{HR.tab=el.dataset.id;refresh();const t=$('.htabs [aria-selected=true]');if(t)t.scrollIntoView({block:'nearest',inline:'nearest'})};

/* ---------- Resumen ---------- */
function hrInicio(){const t=today();const al=hrAlerts();const act=hrAct();
 const pres=act.filter(f=>hrHoursDay(f.id,t).open).length;const pend=S.hrReqs.filter(r=>r.state==='pendiente').length;
 const hoy=act.map(f=>({f,x:hrDay(f,t)})).filter(o=>o.x.sh||o.x.ps.length||o.x.lv);
 const st=o=>o.x.lv?'<span class="badge m">'+esc(HR_REQ_T[o.x.lv.type]||'Licencia')+'</span>':o.x.absent?'<span class="badge bad">Ausente</span>':o.x.open?'<span class="badge ok">Presente</span>'+(o.x.late?' <span class="badge warn">'+o.x.late+' min tarde</span>':''):o.x.ps.length?'<span class="badge">Salió · '+o.x.h.toFixed(2)+' h</span>':'<span class="badge">Por llegar</span>';
 return '<div class="bento">'+hrKpi('Legajos activos',act.length,'','dark')+hrKpi('Presentes ahora',pres,'','yel')+hrKpi('Solicitudes pendientes',pend,pend?'<a href="#/panel/personal" data-a="hrTab" data-id="solicitudes">Revisar</a>':'')+hrKpi('Alertas',al.length,'','pink')+
 '<div class="c s7"><div class="row"><h2 class="sp">Hoy · '+DOW[new Date(now()).getDay()]+' '+fdate(t)+'</h2>'+(hrW()?'<button class="btn g sm" data-a="hrTab" data-id="turnos">'+ic('cal')+'Turnos</button>':'')+'</div>'+(hoy.length?'<div class="list" style="margin-top:6px">'+hoy.map(o=>'<div class="li"><div><b>'+esc(o.f.name)+'</b><div class="sub">'+(o.x.sh?'Turno '+esc(o.x.sh.from)+'–'+esc(o.x.sh.to):'Sin turno cargado')+(o.x.ps.length?' · fichó '+o.x.ps.map(p=>(p.type==='in'?'↘ ':'↗ ')+fdt(p.t).slice(11)).join(' '):'')+'</div></div><div>'+st(o)+'</div></div>').join('')+'</div>':'<p class="sub" style="margin-top:8px">No hay turnos ni fichadas hoy.</p>')+'</div>'+
 '<div class="c s5"><h2>Alertas</h2>'+(al.length?'<div class="list" style="margin-top:6px">'+al.slice(0,10).map(a=>'<div class="li bl '+a.c+'"><span class="bli">'+ic('alert')+'</span><span class="sp">'+esc(a.t)+'</span><button class="btn g sm" data-a="hrTab" data-id="'+a.tab+'">Ver</button></div>').join('')+'</div>':'<p class="sub" style="margin-top:8px">Sin alertas: contratos, documentos y asistencia en orden.</p>')+'</div>'+
 '<div class="c s12"><h2>Qué incluye el módulo</h2><div class="hrfeat">'+[['idcard','Legajos','Datos, contrato, modalidad, PIN y tarjeta de fichaje.'],['cal','Turnos y licencias','Calendario semanal con copia de la semana anterior.'],['clock','Asistencia','Horas, extras, tardanzas, ausencias y reporte para el contador.'],['inbox','Solicitudes','Aprobación en niveles configurables.'],['star','Vacaciones','Días por antigüedad, tomados y saldo.'],['cash','Nómina interna','Liquidación, recibo interno y pago como gasto.'],['file','Documentos','Vencimientos con aviso a 30 días.'],['users','Reclutamiento','Búsquedas y candidatos por etapa.'],['bell','Avisos','Mensajes al personal y lectura en el portal.'],['nfc','Portal del empleado','Kiosco con PIN: fichar, horas, turnos, pedidos y recibos.']].map(x=>'<div>'+ic(x[0])+'<b>'+x[1]+'</b><span class="sub">'+x[2]+'</span></div>').join('')+'</div></div></div>'}

/* ---------- Legajos ---------- */
function hrLegajos(){const m=today().slice(0,7);const [a,b]=monthRange(m);const q=norm(HR.q);
 const l=S.staff.filter(f=>(HR.bajas?f.active===false:f.active!==false)&&(!q||norm(f.name+' '+(f.role||'')+' '+(f.area||'')+' '+(f.dni||'')).includes(q)));
 return '<div class="c"><div class="row" style="margin-bottom:10px"><input id="hrq" data-in="hrq" placeholder="Buscar por nombre, puesto, área o DNI" value="'+esc(HR.q)+'" style="max-width:340px" aria-label="Buscar legajo"><span class="sp"></span><div class="chips"><button class="chip'+(HR.bajas?'':' on')+'" data-a="hrBajas" data-id="0">Activos</button><button class="chip'+(HR.bajas?' on':'')+'" data-a="hrBajas" data-id="1">Dados de baja</button></div></div>'+
 (l.length?'<div class="tw"><table><thead><tr><th>Nombre</th><th>Puesto y área</th><th>Alta</th><th>Fichaje</th><th class="r">Horas del mes</th><th></th></tr></thead><tbody>'+l.map(f=>{const st=hrStats(f,a,b);return '<tr><td><button class="lnk" data-a="hrEmp" data-id="'+f.id+'"><b>'+esc(f.name)+'</b></button><div class="sub">DNI '+(f.dni?maskDoc(f.dni):'—')+(f.cEnd?' · contrato hasta '+fdate(f.cEnd):'')+'</div></td><td>'+esc(f.role||'—')+'<div class="sub">'+esc(f.area||'')+'</div></td><td>'+(f.hire?fdate(f.hire):'—')+'</td><td>'+(f.pinH?'<span class="badge ok">PIN</span> ':'<span class="badge warn">sin PIN</span> ')+(f.cardNonce?'<span class="badge">tarjeta</span>':'')+'</td><td class="r">'+st.h.toFixed(2)+' h'+(st.flags?'<div class="sub bad-t">'+st.flags+' incompleta(s)</div>':'')+'</td><td><div class="act"><button class="btn g sm" data-a="hrEmp" data-id="'+f.id+'">Ver legajo</button></div></td></tr>'}).join('')+'</tbody></table></div>':'<p class="sub">'+(S.staff.length?'Sin resultados.':'Todavía no hay legajos. Tocá «Nuevo legajo».')+'</p>')+
 '<div class="row" style="margin-top:14px"><button class="btn g sm" data-a="hrStaffCsv">'+ic('download')+'Legajos CSV</button></div></div>'}
IN.hrq=el=>{HR.q=el.value;clearTimeout(IN._hq);IN._hq=setTimeout(()=>{refresh();const q=$('#hrq');if(q){q.focus();q.setSelectionRange(q.value.length,q.value.length)}},300)};
A.hrBajas=el=>{HR.bajas=el.dataset.id==='1';refresh()};
A.hrStaffCsv=()=>{const g=mayo('personal','gestionar');download('legajos-personal-'+today()+'.csv',toCSV(['Nombre','DNI','Puesto','Área','Teléfono','Email','Alta','Fin de contrato','Modalidad'].concat(g?['Valor hora','Sueldo mensual','CBU / alias']:[]).concat(['Estado']),S.staff.map(f=>[f.name,f.dni||'',f.role||'',f.area||'',f.phone||'',f.email||'',f.hire||'',f.cEnd||'',f.payMode==='mes'?'mensual':'por hora'].concat(g?[f.rate||0,f.salary||0,f.cbu||'']:[]).concat([f.active===false?'baja':'activo']))),'text/csv');audit('export','legajos del personal')};
A.hrEmp=el=>hrEmpOpen(el.dataset.id);
function hrEmpOpen(id){const f=hrE(id);if(!f)return;const m=today().slice(0,7);const [a,b]=monthRange(m);const st=hrStats(f,a,b);const y=+today().slice(0,4);const g=mayo('personal','gestionar');
 const ent=hrVacEntitled(f,y),tk=hrVacTaken(f,y,'aprobada');const docs=S.hrDocs.filter(d=>d.staffId===id);const reqs=S.hrReqs.filter(r=>r.staffId===id).slice(-5).reverse();
 const row=(k,v)=>v?'<div class="li"><span class="sub">'+k+'</span><span>'+v+'</span></div>':'';
 modal('<div class="row"><h2 class="sp">'+esc(f.name)+'</h2>'+(f.active===false?'<span class="badge bad">Dado de baja '+fdate(f.bajaDate||'')+'</span>':'<span class="badge ok">Activo</span>')+'</div><p class="sub" style="margin:2px 0 10px">'+esc([f.role,f.area].filter(Boolean).join(' · ')||'Sin puesto cargado')+'</p>'+
 '<div class="bento hrmini"><div class="c s4"><span class="lbl">Horas del mes</span><div class="kpi">'+st.h.toFixed(1)+'</div></div><div class="c s4"><span class="lbl">Tardanzas</span><div class="kpi">'+st.lateN+'</div></div><div class="c s4"><span class="lbl">Vacaciones '+y+'</span><div class="kpi">'+(ent-tk)+'</div><span class="sub">de '+ent+' días</span></div></div>'+
 '<div class="list" style="margin-top:10px">'+row('DNI',f.dni?esc(fmtDoc('DNI',f.dni)):'')+row('Teléfono',f.phone?esc(f.phone):'')+row('Email',f.email?esc(f.email):'')+row('Alta',f.hire?fdate(f.hire)+' · '+hrVacYears(f,y)+' año(s)':'')+row('Fin de contrato',f.cEnd?fdate(f.cEnd):'')+row('Modalidad',f.payMode==='mes'?'Mensual'+(g?' · '+money(f.salary||0):''):'Por hora'+(g?' · '+money(f.rate||0):''))+(g?row('CBU / alias',f.cbu?esc(f.cbu):''):'')+row('Contacto de emergencia',f.emerg?esc(f.emerg):'')+row('Notas',f.notes?esc(f.notes):'')+row('PIN de fichaje',f.pinH?'cargado':'<span class="bad-t">sin PIN</span>')+'</div>'+
 '<h3 style="margin-top:14px">Documentos</h3>'+(docs.length?'<div class="list">'+docs.map(d=>'<div class="li"><span>'+esc(HR_DOC_T[d.kind]||d.kind)+' · '+esc(d.name||'')+'</span><span class="sub">'+(d.exp?'vence '+fdate(d.exp):'sin vencimiento')+'</span></div>').join('')+'</div>':'<p class="sub">Sin documentos.</p>')+
 '<h3 style="margin-top:14px">Últimas solicitudes</h3>'+(reqs.length?'<div class="list">'+reqs.map(r=>'<div class="li"><span>'+esc(HR_REQ_T[r.type]||r.type)+' · '+fdate(r.from)+(r.to!==r.from?' al '+fdate(r.to):'')+'</span>'+hrReqBadge(r)+'</div>').join('')+'</div>':'<p class="sub">Sin solicitudes.</p>')+
 '<div class="row" style="margin-top:16px">'+(hrW()?'<button class="btn y sp" data-a="hrEmpEdit" data-id="'+f.id+'">'+ic('edit')+'Editar</button><button class="btn g" data-a="hrCard" data-id="'+f.id+'">'+ic('qr')+'Tarjeta</button>'+(f.active===false?'<button class="btn g" data-a="hrAlta" data-id="'+f.id+'">Reactivar</button>':'<button class="btn g" data-a="hrBaja" data-id="'+f.id+'">Dar de baja</button>'):'')+'<button class="btn g" data-a="mclose">Cerrar</button></div>',{wide:true})}
let HRED='';
function hrEmpForm(f){HRED=f?f.id:'';const n=!f;f=f||{name:'',dni:'',role:'',area:'',phone:'',email:'',hire:today(),cEnd:'',payMode:'hora',rate:'',salary:'',cbu:'',vacExtra:0,emerg:'',notes:''};const g=mayo('personal','gestionar');
 const inp=(id,l,v,x)=>'<div'+(x&&x.full?' style="grid-column:1/-1"':'')+'><label for="'+id+'">'+l+'</label><input id="'+id+'" value="'+esc(v==null?'':v)+'"'+(x&&x.a?' '+x.a:'')+'></div>';
 modal('<h2>'+(n?'Nuevo legajo':'Editar legajo')+'</h2><div class="g2">'+inp('he_n','Nombre y apellido',f.name,{a:'maxlength="80" autofocus'})+inp('he_d','DNI',f.dni,{a:'inputmode="numeric" maxlength="12"'})+inp('he_r','Puesto',f.role,{a:'maxlength="40" placeholder="Ej.: Mostrador, Cultivo, Administración"'})+inp('he_a','Área',f.area,{a:'maxlength="40"'})+inp('he_p','Teléfono / WhatsApp',f.phone,{a:'inputmode="tel" maxlength="20"'})+inp('he_e','Email',f.email,{a:'type="email" maxlength="80"'})+inp('he_h','Fecha de alta',f.hire,{a:'type="date"'})+inp('he_c','Fin de contrato (opcional)',f.cEnd,{a:'type="date"'})+
 '<div><label for="he_m">Modalidad de pago</label><select id="he_m"><option value="hora"'+(f.payMode!=='mes'?' selected':'')+'>Por hora (según fichajes)</option><option value="mes"'+(f.payMode==='mes'?' selected':'')+'>Mensual</option></select></div>'+
 (g?inp('he_v','Valor hora ($)',f.rate,{a:'class="num" type="number" inputmode="decimal" step="any" min="0"'})+inp('he_s','Sueldo mensual ($)',f.salary,{a:'class="num" type="number" inputmode="decimal" step="any" min="0"'})+inp('he_b','CBU o alias para el pago',f.cbu,{a:'maxlength="40"'}):'')+
 inp('he_x','Días extra de vacaciones',f.vacExtra||0,{a:'class="num" type="number" min="0" max="60"'})+inp('he_q','Contacto de emergencia',f.emerg,{a:'maxlength="80"'})+inp('he_o','Notas',f.notes,{full:1,a:'maxlength="200"'})+
 '<div style="grid-column:1/-1"><label for="he_pin">PIN de fichaje y portal (4 a 6 dígitos)'+(f.pinH?' · dejalo vacío para mantener el actual':'')+'</label><input id="he_pin" type="password" inputmode="numeric" autocomplete="new-password" maxlength="6" placeholder="'+(f.pinH?'••••':'Ej.: 4821')+'"></div></div>'+
 '<p class="sub" style="margin-top:8px">El PIN se guarda cifrado (huella SHA-256 con el legajo). No uses fechas de nacimiento ni números repetidos.</p><div class="row" style="margin-top:16px"><button class="btn y lg sp" data-a="hrEmpSave">Guardar</button><button class="btn g lg" data-a="mclose">Cancelar</button></div>',{wide:true})}
A.hrEmpNew=()=>hrEmpForm(null);A.hrEmpEdit=el=>hrEmpForm(hrE(el.dataset.id));
A.hrEmpSave=()=>{const v=id=>{const e=$('#'+id);return e?e.value.trim():null};const name=v('he_n');if(!name)return toast('Escribí el nombre');
 const dni=(v('he_d')||'').replace(/\D/g,'');if(dni&&(dni.length<6||dni.length>9))return toast('El DNI debe tener entre 6 y 9 números');
 const em=v('he_e');if(em&&!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(em))return toast('El email no es válido');
 const hire=v('he_h'),cEnd=v('he_c');if(cEnd&&hire&&cEnd<hire)return toast('El fin de contrato es anterior al alta');
 if(dni&&S.staff.some(x=>x.id!==HRED&&x.dni===dni&&x.active!==false))return toast('Ya hay un legajo activo con ese DNI');
 const pin=(v('he_pin')||'').replace(/\D/g,'');if(pin&&(pin.length<4||pin.length>6))return toast('El PIN tiene que tener 4 a 6 dígitos');
 if(pin&&/^(\d)\1+$/.test(pin))return toast('Elegí un PIN que no sea todos números iguales');
 const f=HRED?hrE(HRED):null;const id=f?f.id:uid();
 if(pin&&S.staff.some(x=>x.id!==id&&x.active!==false&&x.pinH&&x.pinH===hrPinH(x.id,pin)))return toast('Ese PIN ya lo usa otra persona: elegí otro');
 const d={name,dni,role:v('he_r'),area:v('he_a'),phone:(v('he_p')||'').replace(/[^\d+]/g,''),email:em,hire,cEnd,payMode:v('he_m')==='mes'?'mes':'hora',vacExtra:Math.max(0,Math.min(60,parseInt(v('he_x'))||0)),emerg:v('he_q'),notes:v('he_o')};
 if(mayo('personal','gestionar')){const rt=$('#he_v').valueAsNumber,sl=$('#he_s').valueAsNumber;d.rate=isNaN(rt)?0:r2(rt);d.salary=isNaN(sl)?0:r2(sl);d.cbu=v('he_b')}
 if(pin)d.pinH=hrPinH(id,pin);
 if(f){Object.assign(f,d);audit('personal_edicion',name)}else{S.staff.push(Object.assign({id,cardNonce:'',active:true,rate:0,salary:0,cbu:'',created:now()},d));audit('personal_alta',name);const hc=HRHIRE&&S.hrCands.find(c=>c.id===HRHIRE);if(hc)hc.staffId=id}HRHIRE='';
 if(pin)audit('personal_pin',name);persist();closeModal();refresh();toast(f?'Legajo actualizado':'Legajo creado')};
A.hrCard=async el=>{const f=hrE(el.dataset.id);const tok=await cardToken('TF',f);persist();cardModal('Tarjeta de fichaje',f.name,tok,'staff')};
A.hrBaja=el=>{const f=hrE(el.dataset.id);askText({title:'Dar de baja a '+f.name,label:'Motivo de la baja',ok:'Dar de baja',onOk:m=>{f.active=false;f.bajaDate=today();f.bajaMotivo=m;audit('personal_baja',{empleado:f.name,motivo:m});persist();closeModal();refresh();toast('Legajo dado de baja: el historial se conserva')}})};
A.hrAlta=el=>{const f=hrE(el.dataset.id);f.active=true;delete f.bajaDate;delete f.bajaMotivo;audit('personal_reactivacion',f.name);persist();closeModal();refresh();toast('Legajo reactivado')};

/* ---------- Turnos y licencias ---------- */
function hrWeekStart(k){const d=dowK(k);return addDays(k,d===0?-6:1-d)}
function hrTurnos(){if(!HR.week)HR.week=hrWeekStart(today());const ds=hrDays(HR.week,addDays(HR.week,6));const act=hrAct();const w=hrW();const t=today();
 return '<div class="c"><div class="row" style="margin-bottom:10px"><div class="wknav"><button class="ib" data-a="hrWk" data-d="-7" aria-label="Semana anterior">'+ic('chev')+'</button><b>'+fdate(ds[0]).slice(0,5)+' al '+fdate(ds[6])+'</b><button class="ib" data-a="hrWk" data-d="7" aria-label="Semana siguiente" style="transform:scaleX(-1)">'+ic('chev')+'</button><button class="btn g sm" data-a="hrWk" data-d="0">Hoy</button></div><span class="sp"></span>'+(w?'<button class="btn g sm" data-a="hrCopyWk">'+ic('copy')+'Copiar semana anterior</button><button class="btn y sm" data-a="hrReqNew">'+ic('plus')+'Cargar licencia</button>':'')+'</div>'+
 (act.length?'<div class="tw"><table class="hrcal"><thead><tr><th>Empleado</th>'+ds.map(d=>'<th class="'+(d===t?'tdy':'')+'">'+DOW[dowK(d)].slice(0,3)+' '+d.slice(8)+'</th>').join('')+'<th class="r">Horas</th></tr></thead><tbody>'+act.map(f=>{let tot=0;return '<tr><th scope="row">'+esc(f.name)+'<div class="sub">'+esc(f.role||'')+'</div></th>'+ds.map(d=>{const sh=hrShift(f.id,d),lv=hrLeave(f.id,d);if(sh)tot+=((hrMin(sh.to)-hrMin(sh.from)+1440)%1440)/60;
   const inner=lv?'<span class="shl">'+esc(HR_REQ_T[lv.type]||'Licencia')+'</span>':sh?'<span class="shc">'+esc(sh.from)+'–'+esc(sh.to)+'</span>':'<span class="she">'+(w?'+':'—')+'</span>';
   return '<td class="'+(d===t?'tdy':'')+'">'+(w&&!lv?'<button type="button" class="shb" data-a="hrShEdit" data-s="'+f.id+'" data-d="'+d+'" aria-label="Turno de '+esc(f.name)+' el '+fdate(d)+'">'+inner+'</button>':inner)+'</td>'}).join('')+'<td class="r"><b>'+r2(tot)+'</b></td></tr>'}).join('')+'</tbody></table></div>':'<p class="sub">Cargá primero los legajos.</p>')+
 '<p class="sub" style="margin-top:10px">Tocá una celda para cargar o cambiar el turno. Las licencias aprobadas aparecen en el calendario y no cuentan como ausencia.</p></div>'}
A.hrWk=el=>{const d=+el.dataset.d;HR.week=d?addDays(HR.week||hrWeekStart(today()),d):hrWeekStart(today());refresh()};
A.hrShEdit=el=>{const sid=el.dataset.s,d=el.dataset.d,f=hrE(sid),sh=hrShift(sid,d);const prev=S.hrShifts.filter(s=>s.staffId===sid).sort((a,b)=>b.day<a.day?-1:1)[0];
 modal('<h2>Turno de '+esc(f.name)+'</h2><p class="sub">'+DOW[dowK(d)]+' '+fdate(d)+'</p><div class="g2"><div><label for="sh_f">Entrada</label><input id="sh_f" type="time" value="'+esc(sh?sh.from:(prev?prev.from:'10:00'))+'"></div><div><label for="sh_t">Salida</label><input id="sh_t" type="time" value="'+esc(sh?sh.to:(prev?prev.to:'18:00'))+'"></div><div style="grid-column:1/-1"><label for="sh_n">Nota (opcional)</label><input id="sh_n" maxlength="80" value="'+esc(sh?sh.note||'':'')+'"></div></div><label class="chk" for="sh_w"><input type="checkbox" id="sh_w"> Repetir el mismo horario el resto de la semana (lunes a sábado)</label><div class="row" style="margin-top:14px"><button class="btn y lg sp" data-a="hrShSave" data-s="'+sid+'" data-d="'+d+'">Guardar</button>'+(sh?'<button class="btn g lg" data-a="hrShDel" data-s="'+sid+'" data-d="'+d+'">Quitar turno</button>':'')+'<button class="btn g lg" data-a="mclose">Cancelar</button></div>')};
A.hrShSave=el=>{const sid=el.dataset.s,d=el.dataset.d,a=$('#sh_f').value,b=$('#sh_t').value;if(isNaN(hrMin(a))||isNaN(hrMin(b))||a===b)return toast('Revisá el horario');const note=$('#sh_n').value.trim();
 const days=$('#sh_w').checked?hrDays(d,addDays(hrWeekStart(d),5)):[d];
 for(const k of days){if(hrLeave(sid,k))continue;const s=hrShift(sid,k);if(s)Object.assign(s,{from:a,to:b,note});else S.hrShifts.push({id:uid(),staffId:sid,day:k,from:a,to:b,note})}
 audit('rrhh_turno',{empleado:hrE(sid).name,dias:days.length,horario:a+'-'+b});persist();closeModal();refresh()};
A.hrShDel=el=>{S.hrShifts=S.hrShifts.filter(s=>!(s.staffId===el.dataset.s&&s.day===el.dataset.d));audit('rrhh_turno_baja',{empleado:hrE(el.dataset.s).name,dia:el.dataset.d});persist();closeModal();refresh()};
A.hrCopyWk=()=>{const src=hrDays(addDays(HR.week,-7),addDays(HR.week,-1));const l=S.hrShifts.filter(s=>src.includes(s.day));if(!l.length)return toast('La semana anterior no tiene turnos');
 confirmBox({title:'Copiar semana anterior',msg:'Se copian '+l.length+' turno(s) a esta semana. Los turnos que ya cargaste se mantienen.',ok:'Copiar',onOk:()=>{let n=0;for(const s of l){const k=addDays(s.day,7);const f=hrE(s.staffId);if(!f||f.active===false||hrShift(s.staffId,k)||hrLeave(s.staffId,k))continue;S.hrShifts.push({id:uid(),staffId:s.staffId,day:k,from:s.from,to:s.to,note:s.note||''});n++}audit('rrhh_copiar_semana',{turnos:n});persist();refresh();toast(n+' turno(s) copiados')}})};

/* ---------- Asistencia y reporte para el contador ---------- */
function hrAsistencia(){if(!HR.m)HR.m=today().slice(0,7);const [a,b]=monthRange(HR.m);const act=S.staff.filter(f=>f.active!==false||S.fichajes.some(p=>p.staffId===f.id&&dkey(p.t)>=a&&dkey(p.t)<=b));
 const sel=HR.sel&&hrE(HR.sel)?hrE(HR.sel):null;
 return '<div class="c"><div class="row" style="margin-bottom:10px"><label for="hr_m" style="margin:0">Mes</label><input id="hr_m" type="month" data-ch="hrM" value="'+HR.m+'" style="width:auto"><span class="sp"></span>'+(hrW()?'<button class="btn g sm" data-a="hrManual">'+ic('plus')+'Fichada manual</button>':'')+'<button class="btn y sm" data-a="hrRepCsv">'+ic('download')+'Reporte para el contador (CSV)</button></div>'+
 '<div class="tw"><table><thead><tr><th>Empleado</th><th class="r">Días</th><th class="r">Horas</th><th class="r">Extras</th><th class="r">Tardanzas</th><th class="r">Ausencias</th><th class="r">Incompletas</th><th>Licencias</th></tr></thead><tbody>'+act.map(f=>{const s=hrStats(f,a,b);return '<tr><td><button class="lnk" data-a="hrSel" data-id="'+f.id+'"><b>'+esc(f.name)+'</b></button></td><td class="r">'+s.days+'</td><td class="r">'+s.h.toFixed(2)+'</td><td class="r">'+r2(s.ot+s.otSun).toFixed(2)+'</td><td class="r">'+(s.lateN?s.lateN+' ('+s.late+' min)':'0')+'</td><td class="r'+(s.abs?' bad-t':'')+'">'+s.abs+'</td><td class="r'+(s.flags?' bad-t':'')+'">'+s.flags+'</td><td>'+Object.keys(s.lv).map(k=>'<span class="badge m">'+esc(HR_REQ_T[k]||k)+' '+s.lv[k]+'</span>').join(' ')+'</td></tr>'}).join('')+'</tbody></table></div></div>'+
 (sel?hrDetail(sel,a,b):'<p class="sub" style="margin-top:10px">Tocá un nombre para ver el detalle día por día.</p>')}
function hrDetail(f,a,b){const lim=today();const ds=hrDays(a,b>lim?lim:b).reverse();
 return '<div class="c" style="margin-top:14px"><div class="row"><h2 class="sp">Detalle de '+esc(f.name)+'</h2><button class="btn g sm" data-a="hrSel" data-id="">Cerrar detalle</button></div><div class="tw"><table><thead><tr><th>Día</th><th>Turno</th><th>Fichadas</th><th class="r">Horas</th><th>Estado</th></tr></thead><tbody>'+ds.map(d=>{const x=hrDay(f,d);if(!x.sh&&!x.ps.length&&!x.lv)return'';
  return '<tr><td>'+DOW[dowK(d)].slice(0,3)+' '+fdate(d)+'</td><td>'+(x.sh?esc(x.sh.from)+'–'+esc(x.sh.to):'—')+'</td><td>'+x.ps.map(p=>'<span class="badge '+(p.type==='in'?'ok':'warn')+'" title="'+esc(p.method||'tarjeta')+(p.motivo?' · '+esc(p.motivo):'')+'">'+(p.type==='in'?'Ingreso ':'Egreso ')+fdt(p.t).slice(11)+(p.method==='manual'?' ✎':'')+'</span>').join(' ')+'</td><td class="r">'+x.h.toFixed(2)+'</td><td>'+(x.lv?'<span class="badge m">'+esc(HR_REQ_T[x.lv.type])+'</span> ':'')+(x.absent?'<span class="badge bad">Ausente</span> ':'')+(x.late?'<span class="badge warn">'+x.late+' min tarde</span> ':'')+(x.flag?'<span class="badge bad">Incompleta</span>':'')+(x.ot?' <span class="badge">+'+x.ot+' h extra</span>':'')+'</td></tr>'}).join('')+'</tbody></table></div><p class="sub" style="margin-top:8px">✎ = fichada cargada a mano (queda en la auditoría con su motivo).</p></div>'}
CH.hrM=el=>{HR.m=el.value||today().slice(0,7);refresh()};
A.hrSel=el=>{HR.sel=el.dataset.id;refresh()};
A.hrManual=()=>{if(!hrAct().length)return toast('No hay legajos activos');modal('<h2>Fichada manual</h2><p class="sub" style="margin:4px 0 8px">Para corregir un olvido. Queda marcada y auditada con el motivo.</p><div class="g2"><div><label for="mf_e">Empleado</label>'+hrEmpSel('mf_e',HR.sel)+'</div><div><label for="mf_t">Tipo</label><select id="mf_t"><option value="in">Ingreso</option><option value="out">Egreso</option></select></div><div><label for="mf_d">Día</label><input id="mf_d" type="date" max="'+today()+'" value="'+today()+'"></div><div><label for="mf_h">Hora</label><input id="mf_h" type="time" value="'+fdt(now()).slice(11)+'"></div><div style="grid-column:1/-1"><label for="mf_m">Motivo (obligatorio)</label><input id="mf_m" maxlength="120" placeholder="Ej.: se olvidó de fichar la salida"></div></div><div class="row" style="margin-top:14px"><button class="btn y lg sp" data-a="hrManualOk">Guardar fichada</button><button class="btn g lg" data-a="mclose">Cancelar</button></div>')};
A.hrManualOk=()=>{const f=hrE($('#mf_e').value),d=$('#mf_d').value,h=$('#mf_h').value,m=$('#mf_m').value.trim();if(!f||!d||!h)return toast('Completá empleado, día y hora');if(m.length<3)return toast('Escribí el motivo');
 const ts=hrTs(d,h);if(ts>now()+60000)return toast('La hora no puede ser futura');
 S.fichajes.push({id:uid(),staffId:f.id,t:ts,type:$('#mf_t').value,method:'manual',motivo:m,by:SES.name});audit('fichaje_manual',{empleado:f.name,dia:d,hora:h,tipo:$('#mf_t').value,motivo:m});persist();closeModal();HR.sel=f.id;HR.m=d.slice(0,7);refresh();toast('Fichada cargada')};
A.hrRepCsv=()=>{const [a,b]=monthRange(HR.m||today().slice(0,7));const rows=[];
 for(const f of S.staff){const s=hrStats(f,a,b);if(f.active===false&&!s.h)continue;rows.push([f.name,f.dni||'',f.role||'',HR.m||today().slice(0,7),s.days,s.h,s.ot,s.otSun,s.lateN,s.late,s.abs,s.flags,Object.keys(s.lv).map(k=>(HR_REQ_T[k]||k)+': '+s.lv[k]).join(' | ')])}
 download('asistencia-'+(HR.m||today().slice(0,7))+'.csv',toCSV(['Empleado','DNI','Puesto','Mes','Días trabajados','Horas','Horas extra','Horas extra domingo','Tardanzas','Minutos de tardanza','Ausencias','Fichadas incompletas','Licencias (días)'],rows),'text/csv');audit('export','reporte de asistencia '+(HR.m||''))};

/* ---------- Solicitudes con aprobación en niveles ---------- */
function hrCanStep(step){if(step==='admin')return can('admin');if(step==='rrhh')return mayo('personal','gestionar');return mayo('personal','cargar')}
const hrNextStep=r=>{const fl=r.flow||hrCfg().flow;return fl[(r.steps||[]).filter(s=>s.ok).length]||null};
function hrReqBadge(r){const c={pendiente:'warn',aprobada:'ok',rechazada:'bad',cancelada:''}[r.state];const nx=r.state==='pendiente'?hrNextStep(r):null;return '<span class="badge '+c+'">'+esc(r.state)+(nx?' · falta '+esc(HR_FLOW_T[nx]):'')+'</span>'}
function hrSolicitudes(){const l=S.hrReqs.filter(r=>HR.rf==='todas'||r.state===HR.rf).slice().sort((a,b)=>b.created-a.created);
 return '<div class="c"><div class="row" style="margin-bottom:10px"><div class="chips">'+[['pendiente','Pendientes'],['aprobada','Aprobadas'],['rechazada','Rechazadas'],['todas','Todas']].map(x=>'<button class="chip'+(HR.rf===x[0]?' on':'')+'" data-a="hrRf" data-id="'+x[0]+'">'+x[1]+'</button>').join('')+'</div><span class="sp"></span>'+(hrW()?'<button class="btn y sm" data-a="hrReqNew">'+ic('plus')+'Nueva solicitud</button>':'')+'</div>'+
 '<p class="sub" style="margin-bottom:8px">Circuito de aprobación: '+hrCfg().flow.map(s=>esc(HR_FLOW_T[s])).join(' → ')+'. El personal también puede pedirlas desde el portal (kiosco).</p>'+
 (l.length?'<div class="list">'+l.map(r=>{const f=hrE(r.staffId);const nx=r.state==='pendiente'?hrNextStep(r):null;const dias=hrDays(r.from,r.to).length;
  return '<div class="li hreq"><div style="min-width:0;flex:1"><b>'+esc(f?f.name:'—')+'</b> · '+esc(HR_REQ_T[r.type]||r.type)+' · '+fdate(r.from)+(r.to!==r.from?' al '+fdate(r.to):'')+' <span class="sub">('+dias+' día'+(dias>1?'s':'')+')</span>'+(r.note?'<div class="sub">«'+esc(r.note)+'»</div>':'')+
  '<div class="hsteps">'+(r.flow||hrCfg().flow).map((s,i)=>{const st=(r.steps||[])[i];return '<span class="hstep '+(st?(st.ok?'ok':'no'):'')+'" title="'+(st?esc(st.by)+' · '+fdt(st.t)+(st.note?' · '+esc(st.note):''):'Pendiente')+'">'+(st?(st.ok?'✓ ':'✕ '):'')+esc(HR_FLOW_T[s])+'</span>'}).join('<span class="harr">›</span>')+'<span class="sub"> · '+(r.origen==='portal'?'pedida en el portal':'cargada por '+esc(r.by||''))+' el '+fdt(r.created)+'</span></div></div>'+
  '<div class="act">'+hrReqBadge(r)+(nx&&hrCanStep(nx)?'<button class="btn y sm" data-a="hrReqOk" data-id="'+r.id+'">Aprobar como '+esc(HR_FLOW_T[nx])+'</button><button class="btn g sm" data-a="hrReqNo" data-id="'+r.id+'">Rechazar</button>':'')+(r.state==='pendiente'&&hrW()?'<button class="btn g sm" data-a="hrReqCancel" data-id="'+r.id+'">Anular</button>':'')+'</div></div>'}).join('')+'</div>':'<p class="sub">No hay solicitudes en esta lista.</p>')+'</div>'}
A.hrRf=el=>{HR.rf=el.dataset.id;refresh()};
function hrReqForm(sid,portal){modal('<h2>'+(portal?'Pedir licencia o vacaciones':'Nueva solicitud')+'</h2><div class="g2">'+(portal?'':'<div><label for="rq_e">Empleado</label>'+hrEmpSel('rq_e',sid)+'</div>')+'<div><label for="rq_t">Tipo</label><select id="rq_t">'+Object.keys(HR_REQ_T).map(k=>'<option value="'+k+'">'+HR_REQ_T[k]+'</option>').join('')+'</select></div><div><label for="rq_f">Desde</label><input id="rq_f" type="date" value="'+today()+'"></div><div><label for="rq_h">Hasta</label><input id="rq_h" type="date" value="'+today()+'"></div><div style="grid-column:1/-1"><label for="rq_n">Comentario (opcional)</label><input id="rq_n" maxlength="160"></div></div><div class="row" style="margin-top:14px"><button class="btn y lg sp" data-a="hrReqSave"'+(portal?' data-portal="'+esc(sid)+'"':'')+'>Enviar solicitud</button><button class="btn g lg" data-a="mclose">Cancelar</button></div>')}
A.hrReqNew=()=>{if(!hrAct().length)return toast('No hay legajos activos');hrReqForm(HR.sel||'',false)};
A.hrReqSave=el=>{const portal=el.dataset.portal;const sid=portal||$('#rq_e').value;const f=hrE(sid);const a=$('#rq_f').value,b=$('#rq_h').value;if(!f||!a||!b)return toast('Completá las fechas');if(b<a)return toast('«Hasta» es anterior a «Desde»');
 if(hrDays(a,b).length>120)return toast('Máximo 120 días por solicitud');
 if(S.hrReqs.some(r=>r.staffId===sid&&(r.state==='pendiente'||r.state==='aprobada')&&r.from<=b&&r.to>=a))return toast('Ya hay una solicitud para esas fechas');
 const r={id:uid(),staffId:sid,type:$('#rq_t').value,from:a,to:b,note:$('#rq_n').value.trim(),state:'pendiente',flow:hrCfg().flow.slice(),steps:[],created:now(),by:portal?f.name:SES.name,origen:portal?'portal':'panel'};
 if(r.type==='vacaciones'){const y=+a.slice(0,4);const sal=hrVacEntitled(f,y)-hrVacTaken(f,y,'aprobada')-hrVacTaken(f,y,'pendiente');if(hrDays(a,b).length>sal&&!confirm('Pide más días de los que le quedan ('+sal+'). ¿Enviar igual?'))return}
 S.hrReqs.push(r);audit('rrhh_solicitud',{empleado:f.name,tipo:r.type,desde:a,hasta:b,origen:r.origen});persist();closeModal();if(portal){HRK.sec='solic';hrkTouch()}refresh();toast('Solicitud enviada')};
A.hrReqOk=el=>{const r=S.hrReqs.find(x=>x.id===el.dataset.id);const nx=hrNextStep(r);if(!nx||!hrCanStep(nx))return toast('No te corresponde este paso');
 r.steps=(r.steps||[]).concat([{lvl:nx,ok:true,by:SES.name,t:now()}]);if(!hrNextStep(r))r.state='aprobada';
 if(r.state==='aprobada')S.hrShifts=S.hrShifts.filter(s=>!(s.staffId===r.staffId&&s.day>=r.from&&s.day<=r.to));
 audit('rrhh_aprobacion',{empleado:(hrE(r.staffId)||{}).name,paso:HR_FLOW_T[nx],estado:r.state});persist();refresh();toast(r.state==='aprobada'?'Solicitud aprobada':'Aprobado: pasa a '+HR_FLOW_T[hrNextStep(r)])};
A.hrReqNo=el=>{const r=S.hrReqs.find(x=>x.id===el.dataset.id);const nx=hrNextStep(r);if(!nx||!hrCanStep(nx))return toast('No te corresponde este paso');
 askText({title:'Rechazar solicitud',label:'Motivo (lo ve el empleado en el portal)',ok:'Rechazar',onOk:m=>{r.steps=(r.steps||[]).concat([{lvl:nx,ok:false,by:SES.name,t:now(),note:m}]);r.state='rechazada';audit('rrhh_rechazo',{empleado:(hrE(r.staffId)||{}).name,motivo:m});persist();refresh()}})};
A.hrReqCancel=el=>confirmBox({title:'Anular solicitud',msg:'La solicitud queda anulada (se conserva en el historial).',ok:'Anular',danger:true,onOk:()=>{const r=S.hrReqs.find(x=>x.id===el.dataset.id);r.state='cancelada';audit('rrhh_solicitud_anulada',(hrE(r.staffId)||{}).name);persist();refresh()}});

/* ---------- Vacaciones ---------- */
function hrVacaciones(){const y=HR.vy||+today().slice(0,4);const c=hrCfg();
 return '<div class="c"><div class="row" style="margin-bottom:10px"><label for="hr_vy" style="margin:0">Año</label><select id="hr_vy" class="sel" data-ch="hrVy">'+[y-1,y,y+1].map(v=>'<option'+(v===y?' selected':'')+'>'+v+'</option>').join('')+'</select><span class="sp"></span>'+(hrW()?'<button class="btn y sm" data-a="hrReqNew">'+ic('plus')+'Cargar vacaciones</button>':'')+'</div>'+
 '<div class="tw"><table><thead><tr><th>Empleado</th><th>Alta</th><th class="r">Antigüedad</th><th class="r">Corresponden</th><th class="r">Tomadas</th><th class="r">Pedidas</th><th class="r">Saldo</th><th style="min-width:140px"></th></tr></thead><tbody>'+hrAct().map(f=>{const e=hrVacEntitled(f,y),tk=hrVacTaken(f,y,'aprobada'),pe=hrVacTaken(f,y,'pendiente'),sal=e-tk;const pct=e?Math.min(100,Math.round(tk/e*100)):0;
  return '<tr><td><b>'+esc(f.name)+'</b></td><td>'+(f.hire?fdate(f.hire):'<span class="bad-t">sin fecha</span>')+'</td><td class="r">'+(f.hire?hrVacYears(f,y)+' año(s)':'—')+'</td><td class="r">'+e+'</td><td class="r">'+tk+'</td><td class="r">'+pe+'</td><td class="r"><b class="'+(sal<0?'bad-t':'')+'">'+sal+'</b></td><td><div class="hbar" role="img" aria-label="'+tk+' de '+e+' días tomados"><i style="width:'+pct+'%"></i></div></td></tr>'}).join('')+'</tbody></table></div>'+
 '<p class="sub" style="margin-top:10px">Días corridos según antigüedad al 31/12: '+c.vacTable.map(x=>'desde '+x[0]+' año(s): '+x[1]).join(' · ')+'. La tabla se cambia en Ajustes [VERIFICAR con el contador o el convenio].</p></div>'}
CH.hrVy=el=>{HR.vy=+el.value;refresh()};

/* ---------- Nómina interna ---------- */
function hrNomina(){if(!HR.m)HR.m=today().slice(0,7);const per=HR.m;const lines=hrPayCalc(per);const saved=S.hrPays.filter(p=>p.period===per);const c=hrCfg();
 const tot=lines.reduce((a,l)=>a+l.net,0);
 return '<div class="notice">'+ic('alert')+'<span class="sp">Liquidación <b>interna</b> para ordenar los pagos. No reemplaza el recibo de haberes legal ni calcula aportes: revisalo con el contador [VERIFICAR].</span></div>'+
 '<div class="c"><div class="row" style="margin-bottom:10px"><label for="hr_pm" style="margin:0">Período</label><input id="hr_pm" type="month" data-ch="hrM" value="'+per+'" style="width:auto"><span class="sp"></span><button class="btn g sm" data-a="hrPayCsv">'+ic('download')+'CSV</button><button class="btn y sm" data-a="hrPayGen">Guardar liquidación del período</button></div>'+
 '<div class="tw"><table><thead><tr><th>Empleado</th><th>Modalidad</th><th class="r">Horas</th><th class="r">Básico</th><th class="r">Extras</th><th class="r">Desc.</th><th class="r">Bruto</th>'+(c.deds.length?'<th class="r">Deducciones</th>':'')+'<th class="r">Neto</th><th>Estado</th><th></th></tr></thead><tbody>'+lines.map(l=>{const sp=saved.find(p=>p.staffId===l.staffId);
  return '<tr><td><b>'+esc(l.name)+'</b><div class="sub">'+esc(l.role)+'</div></td><td>'+l.mode+'</td><td class="r">'+l.hours.toFixed(2)+(l.ot?'<div class="sub">+'+l.ot+' extra</div>':'')+'</td><td class="r">'+money(l.base)+'</td><td class="r">'+money(l.otAmt)+'</td><td class="r">'+(l.lateAmt+l.absAmt?'-'+money(l.lateAmt+l.absAmt):'—')+'</td><td class="r">'+money(l.gross)+'</td>'+(c.deds.length?'<td class="r">-'+money(l.deds.reduce((a,d)=>a+d.a,0))+'</td>':'')+'<td class="r"><b>'+money(l.net)+'</b></td><td>'+(sp?(sp.paid?'<span class="badge ok">Pagada '+fdate(dkey(sp.paidT))+'</span>':'<span class="badge warn">Guardada</span>'+(sp.net!==l.net?'<div class="sub bad-t">cambió: volvé a guardar</div>':'')):'<span class="badge">Sin guardar</span>')+'</td><td><div class="act">'+(sp?'<button class="btn g sm" data-a="hrRecibo" data-id="'+sp.id+'">'+ic('print')+'Recibo</button>'+(sp.paid?'':'<button class="btn y sm" data-a="hrPaid" data-id="'+sp.id+'">Registrar pago</button>'):'')+'</div></td></tr>'}).join('')+'</tbody><tfoot><tr><td colspan="'+(c.deds.length?8:7)+'"><b>Total neto del período</b></td><td class="r"><b>'+money(tot)+'</b></td><td colspan="2"></td></tr></tfoot></table></div>'+
 '<p class="sub" style="margin-top:10px">Extras: más de '+c.otDaily+' h por día al '+(c.otFactor*100)+'% ('+(c.otSun*100)+'% los domingos). Tolerancia de llegada: '+c.tol+' min.'+(c.lateDisc?' Descuenta tardanzas.':'')+(c.absDisc?' Descuenta ausencias (mensuales).':'')+' Se cambia en Ajustes.</p></div>'}
A.hrPayGen=()=>{const per=HR.m||today().slice(0,7);const lines=hrPayCalc(per);if(!lines.length)return toast('No hay personal con horas en el período');
 confirmBox({title:'Guardar liquidación '+per,msg:'Se guarda una foto de la liquidación de '+lines.length+' persona(s). Las ya pagadas no se tocan.',ok:'Guardar',onOk:()=>{let n=0;for(const l of lines){const id='py_'+per+'_'+l.staffId;const p=S.hrPays.find(x=>x.id===id);if(p&&p.paid)continue;const d=Object.assign({id,period:per,t:now(),by:SES.name,paid:false},l);if(p)Object.assign(p,d);else S.hrPays.push(d);n++}audit('rrhh_nomina',{periodo:per,personas:n});persist();refresh();toast('Liquidación guardada')}})};
A.hrPayCsv=()=>{const per=HR.m||today().slice(0,7);const c=hrCfg();download('nomina-'+per+'.csv',toCSV(['Empleado','Puesto','Modalidad','Horas','Horas extra','Minutos tarde','Ausencias','Básico','Extras','Desc. tardanzas','Desc. ausencias','Bruto'].concat(c.deds.map(d=>d.n)).concat(['Neto','CBU / alias']),hrPayCalc(per).map(l=>[l.name,l.role,l.mode,l.hours,l.ot,l.late,l.abs,l.base,l.otAmt,l.lateAmt,l.absAmt,l.gross].concat(l.deds.map(d=>d.a)).concat([l.net,(hrE(l.staffId)||{}).cbu||'']))),'text/csv');audit('export','nómina '+per)};
A.hrRecibo=el=>{const p=S.hrPays.find(x=>x.id===el.dataset.id);const f=hrE(p.staffId)||{name:p.name};
 modal('<div class="printable recibo"><h2>Recibo interno · '+esc(p.period)+'</h2><p class="sub">'+esc(S.org.nameLegal||S.org.nameCom)+' · CUIT '+esc(S.org.cuit||'')+'</p><div class="list" style="margin-top:10px"><div class="li"><span>Empleado</span><b>'+esc(f.name)+'</b></div><div class="li"><span>DNI</span><span>'+esc(f.dni?fmtDoc('DNI',f.dni):'—')+'</span></div><div class="li"><span>Puesto</span><span>'+esc(p.role||'—')+'</span></div><div class="li"><span>Modalidad</span><span>'+esc(p.mode)+' · '+p.hours+' h trabajadas</span></div><div class="li"><span>Básico</span><span>'+money(p.base)+'</span></div><div class="li"><span>Horas extra ('+p.ot+' h)</span><span>'+money(p.otAmt)+'</span></div>'+(p.lateAmt?'<div class="li"><span>Descuento por tardanzas</span><span>-'+money(p.lateAmt)+'</span></div>':'')+(p.absAmt?'<div class="li"><span>Descuento por ausencias</span><span>-'+money(p.absAmt)+'</span></div>':'')+'<div class="li"><span><b>Bruto</b></span><b>'+money(p.gross)+'</b></div>'+(p.deds||[]).map(d=>'<div class="li"><span>'+esc(d.n)+'</span><span>-'+money(d.a)+'</span></div>').join('')+'<div class="li"><span><b>Neto a cobrar</b></span><b style="font-size:20px">'+money(p.net)+'</b></div></div>'+(p.paid?'<p class="sub" style="margin-top:8px">Pagado el '+fdt(p.paidT)+' · '+esc(p.paidMedio||'')+'</p>':'')+'<p class="sub" style="margin-top:12px">Documento interno de '+esc(S.org.brand||'')+'. No reemplaza el recibo de haberes legal.</p><div class="firmas"><span>Firma del empleado</span><span>Firma de la organización</span></div></div><div class="row no-p" style="margin-top:14px"><button class="btn y sp" data-a="tkPrint">'+ic('print')+'Imprimir</button><button class="btn g" data-a="mclose">Cerrar</button></div>')};
A.hrPaid=el=>{const p=S.hrPays.find(x=>x.id===el.dataset.id);const gOk=mayo('gastos','cargar')&&rubrosFor('egreso').length;const hon=S.rubros.find(r=>r.id==='r_hon'&&r.active!==false);
 modal('<h2>Registrar pago</h2><p class="sub" style="margin:4px 0 8px">'+esc(p.name)+' · '+esc(p.period)+' · neto <b>'+money(p.net)+'</b></p><div class="g2"><div><label for="hp_m">Medio</label><select id="hp_m"><option value="transferencia">Transferencia</option><option value="efectivo">Efectivo</option></select></div>'+(gOk?'<div><label for="hp_r">Rubro del gasto</label>'+rubroSelect('hp_r','egreso',hon?hon.id:'')+'</div>':'')+'</div>'+(gOk?'<label class="chk" for="hp_g"><input type="checkbox" id="hp_g" checked> Registrarlo también en Gastos (categoría «Sueldos y honorarios»)</label>'+(S.cash.open?'<label class="chk" for="hp_k"><input type="checkbox" id="hp_k"> Salió del efectivo de la caja abierta</label>':''):'<p class="sub">Sin permiso de Gastos: sólo se marca como pagada.</p>')+'<div class="row" style="margin-top:14px"><button class="btn y lg sp" data-a="hrPaidOk" data-id="'+p.id+'">Confirmar pago</button><button class="btn g lg" data-a="mclose">Cancelar</button></div>')};
A.hrPaidOk=el=>{const p=S.hrPays.find(x=>x.id===el.dataset.id);const medio=$('#hp_m').value;const g=$('#hp_g');let gid='';
 if(g&&g.checked){const ru=rubroSel($('#hp_r').value,'egreso');if(!ru)return toast('Elegí el rubro del gasto');const k=$('#hp_k');
  const gs={id:uid(),date:today(),cat:'Sueldos y honorarios',prov:p.name,desc:'Nómina '+p.period,amount:r2(p.net),medio,rubro:ru,user:SES.name,hrPay:p.id};
  if(k&&k.checked){if(medio!=='efectivo')return toast('Sólo un pago en efectivo sale de la caja');if(p.net>cajaStats().esperado)return toast('No hay tanto efectivo en la caja');cashAdd('egreso',p.net,'Sueldo: '+p.name,gs.id,ru.id);gs.cajaMove=true}
  S.gastos.push(gs);gid=gs.id}
 Object.assign(p,{paid:true,paidT:now(),paidMedio:medio,gastoId:gid,paidBy:SES.name});audit('rrhh_pago',{empleado:p.name,periodo:p.period,neto:p.net,medio});persist();closeModal();refresh();toast('Pago registrado')};

/* ---------- Documentos ---------- */
function hrDocumentos(){const t=today(),lim=addDays(t,30);const l=S.hrDocs.filter(d=>!HR.docf||d.staffId===HR.docf).sort((a,b)=>(a.exp||'9')<(b.exp||'9')?-1:1);
 return '<div class="c"><div class="row" style="margin-bottom:10px">'+hrEmpSel('hr_df',HR.docf,'Todo el personal','Filtrar por empleado').replace('<select ','<select data-ch="hrDf" ')+'<span class="sp"></span>'+(hrW()?'<button class="btn y sm" data-a="hrDocNew">'+ic('plus')+'Cargar documento</button>':'')+'</div>'+
 (l.length?'<div class="tw"><table><thead><tr><th>Empleado</th><th>Tipo</th><th>Descripción</th><th>Vencimiento</th><th>Archivo</th><th></th></tr></thead><tbody>'+l.map(d=>{const f=hrE(d.staffId);const st=!d.exp?'':d.exp<t?'<span class="badge bad">Vencido</span>':d.exp<=lim?'<span class="badge warn">Vence pronto</span>':'<span class="badge ok">Vigente</span>';
  return '<tr><td>'+esc(f?f.name:'—')+'</td><td>'+esc(HR_DOC_T[d.kind]||d.kind)+'</td><td>'+esc(d.name||'')+'<div class="sub">'+fdt(d.t)+' · '+esc(d.by||'')+'</div></td><td>'+(d.exp?fdate(d.exp)+' '+st:'—')+'</td><td>'+(S.hrFiles[d.id]?'<button class="btn g sm" data-a="hrFile" data-id="'+d.id+'">'+ic('download')+'Abrir</button>':d.hasFile?'<span class="sub">en otro equipo</span>':'—')+'</td><td>'+(mayo('personal','gestionar')?'<button class="btn g sm" data-a="hrDocDel" data-id="'+d.id+'" aria-label="Borrar documento">'+ic('trash')+'</button>':'')+'</td></tr>'}).join('')+'</tbody></table></div>':'<p class="sub">Sin documentos cargados.</p>')+
 '<p class="sub" style="margin-top:10px">Los archivos (PDF o imagen, hasta 1,5 MB) quedan guardados cifrados en este equipo y en su respaldo; en la nube viaja sólo la descripción y el vencimiento. Se avisa 30 días antes de cada vencimiento.</p></div>'}
CH.hrDf=el=>{HR.docf=el.value;refresh()};
A.hrDocNew=()=>{if(!hrAct().length)return toast('No hay legajos activos');modal('<h2>Cargar documento</h2><div class="g2"><div><label for="dc_e">Empleado</label>'+hrEmpSel('dc_e',HR.docf)+'</div><div><label for="dc_k">Tipo</label><select id="dc_k">'+Object.keys(HR_DOC_T).map(k=>'<option value="'+k+'">'+HR_DOC_T[k]+'</option>').join('')+'</select></div><div style="grid-column:1/-1"><label for="dc_n">Descripción</label><input id="dc_n" maxlength="100" placeholder="Ej.: Contrato a plazo fijo 2026"></div><div><label for="dc_x">Vence (opcional)</label><input id="dc_x" type="date"></div><div><label for="dc_f">Archivo (opcional)</label><input id="dc_f" type="file" accept="application/pdf,image/png,image/jpeg,image/webp"></div></div><div class="row" style="margin-top:14px"><button class="btn y lg sp" data-a="hrDocSave">Guardar</button><button class="btn g lg" data-a="mclose">Cancelar</button></div>')};
A.hrDocSave=async()=>{const sid=$('#dc_e').value,f=hrE(sid);if(!f)return toast('Elegí el empleado');const inp=$('#dc_f');let file=null;
 if(inp&&inp.files&&inp.files[0]){const x=inp.files[0];if(x.size>HR_FILE_MAX)return toast('El archivo supera 1,5 MB');if(!/^(image\/(png|jpeg|webp)|application\/pdf)$/.test(x.type))return toast('Sólo PDF, JPG, PNG o WEBP');
  file=await new Promise(res=>{const rd=new FileReader();rd.onload=()=>res(rd.result);rd.onerror=()=>res(null);rd.readAsDataURL(x)});if(!file)return toast('No se pudo leer el archivo')}
 const d={id:uid(),staffId:sid,kind:$('#dc_k').value,name:$('#dc_n').value.trim(),exp:$('#dc_x').value||'',t:now(),by:SES.name,hasFile:!!file,fname:file?inp.files[0].name.slice(0,80):''};
 S.hrDocs.push(d);if(file)S.hrFiles[d.id]=file;audit('rrhh_documento',{empleado:f.name,tipo:d.kind,vence:d.exp});persist();closeModal();refresh();toast('Documento guardado')};
