/* ---------- Ajustes (administración) ---------- */
function hrAjustes(){const c=hrCfg();const n=(id,l,v,a)=>'<div><label for="'+id+'">'+l+'</label><input class="num" id="'+id+'" type="number" step="any" value="'+v+'" '+(a||'')+'></div>';
 return '<div class="bento"><div class="c s6"><h2>Asistencia y horas extra</h2><div class="g2">'+n('ha_tol','Tolerancia de llegada (min)',c.tol,'min="0" max="120"')+n('ha_od','Horas por día antes de extras',c.otDaily,'min="1" max="16"')+n('ha_of','Factor de horas extra',c.otFactor,'min="1" max="3"')+n('ha_os','Factor de extras en domingo',c.otSun,'min="1" max="3"')+n('ha_mh','Horas mensuales (para el valor hora de mensuales)',c.monthHours,'min="1" max="300"')+'</div><label class="chk" for="ha_ld"><input type="checkbox" id="ha_ld"'+(c.lateDisc?' checked':'')+'> Descontar tardanzas en la nómina interna</label><label class="chk" for="ha_ad"><input type="checkbox" id="ha_ad"'+(c.absDisc?' checked':'')+'> Descontar ausencias a mensuales</label></div>'+
 '<div class="c s6"><h2>Aprobación de solicitudes</h2><p class="sub" style="margin:4px 0 8px">Pasos en orden. Supervisor = permiso «Cargar» en Personal; RR. HH. = «Gestionar»; Administración = administrador.</p>'+['supervisor','rrhh','admin'].map(k=>'<label class="chk" for="ha_f_'+k+'"><input type="checkbox" id="ha_f_'+k+'"'+(c.flow.includes(k)?' checked':'')+'> '+HR_FLOW_T[k]+'</label>').join('')+'<label class="chk" for="ha_po"><input type="checkbox" id="ha_po"'+(c.portal!==false?' checked':'')+'> Portal del empleado en el kiosco (horas, turnos, pedidos, avisos y recibos)</label></div>'+
 '<div class="c s6"><h2>Vacaciones por antigüedad</h2><label for="ha_vt">Años:días, separados por coma</label><input id="ha_vt" value="'+esc(c.vacTable.map(x=>x[0]+':'+x[1]).join(', '))+'"><p class="sub" style="margin-top:6px">Por defecto 0:14, 5:21, 10:28, 20:35 (días corridos) [VERIFICAR con el convenio].</p></div>'+
 '<div class="c s6"><h2>Deducciones de la nómina interna</h2><label for="ha_de">Una por línea: Nombre: porcentaje</label><textarea id="ha_de" placeholder="Ej.: Adelanto: 0">'+esc(c.deds.map(d=>d.n+': '+d.pct).join('\n'))+'</textarea><p class="sub" style="margin-top:6px">No se inventan alícuotas: cargalas con el contador.</p></div>'+
 '<div class="c s12"><button class="btn y" data-a="hrCfgSave">Guardar ajustes de RR. HH.</button></div></div>'}
A.hrCfgSave=()=>{if(!can('admin'))return toast('Sólo un administrador cambia estos ajustes');const g=id=>$('#'+id).valueAsNumber;
 const flow=['supervisor','rrhh','admin'].filter(k=>$('#ha_f_'+k).checked);if(!flow.length)return toast('Elegí al menos un paso de aprobación');
 const vt=[];for(const p of $('#ha_vt').value.split(',')){const m=p.trim().match(/^(\d{1,2})\s*:\s*(\d{1,3})$/);if(!m)return toast('Revisá la tabla de vacaciones (ej.: 0:14, 5:21)');vt.push([+m[1],+m[2]])}vt.sort((a,b)=>a[0]-b[0]);
 const deds=[];for(const l of $('#ha_de').value.split('\n')){if(!l.trim())continue;const m=l.match(/^(.{1,40}?)\s*:\s*([\d.,]+)\s*%?\s*$/);if(!m)return toast('Revisá las deducciones (ej.: Adelanto: 5)');const pc=parseNum(m[2]);if(isNaN(pc)||pc<0||pc>100)return toast('Porcentaje inválido: '+m[2]);deds.push({n:m[1].trim(),pct:pc})}
 const cl=(v,a,b,d)=>isNaN(v)?d:Math.min(b,Math.max(a,v));
 S.org.hr={tol:cl(g('ha_tol'),0,120,10),otDaily:cl(g('ha_od'),1,16,8),otFactor:cl(g('ha_of'),1,3,1.5),otSun:cl(g('ha_os'),1,3,2),monthHours:cl(g('ha_mh'),1,300,200),lateDisc:$('#ha_ld').checked,absDisc:$('#ha_ad').checked,flow,vacTable:vt,deds,portal:$('#ha_po').checked};
 audit('config_rrhh',S.org.hr);persist();toast('Ajustes guardados');refresh()};

